//! FreeBASIC: `azul.bi` (generated by `doc/src/codegen/v2/lang_freebasic`,
//! `#include once "azul.bi"`).
//!
//! Spellings are the C ones: `Declare Function AzCssProperty_textColor`,
//! variant constructors `AzLayoutWidth_px(..)`, enum members
//! `AzLayoutDisplay_Flex`, types `AzColorU`; a struct is an anonymous
//! `Type<AzColorU>(255, 0, 0, 255)` (fields in declaration order). Calls
//! and `Type<..>(..)` nest; a Vec needs a `Dim`med array
//! ([`super::linear`]): `AzXVec_copyFromPtr(@t1(0), n)`. Strings go through
//! a local `CssStr` helper over `AzString_copyFromBytes` (the `AzStr` of
//! `examples/freebasic`).
//!
//! Limitation: `azul.bi` declares no type for the `CssPropertyValue<T>`
//! aliases (`AzLayoutWidthValue`, ...), so they - and hand-built
//! `CssProperty` unions, whose union names them - cannot be written.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{module_any, variant_ctor_method},
    CodegenBackend, GeneratedFile,
};

/// The FreeBASIC printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct FreeBasic;

fn apply(f: &str, args: &[String]) -> String {
    format!("{f}({})", args.join(", "))
}

/// A BASIC string expression: printable ASCII in quotes (`"` doubled),
/// other bytes joined in as `Chr(n)`.
pub(crate) fn basic_string(s: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut run = String::new();
    for b in s.bytes() {
        if (0x20..0x7f).contains(&b) {
            if b == b'"' {
                run.push_str("\"\"");
            } else {
                run.push(char::from(b));
            }
        } else {
            if !run.is_empty() || parts.is_empty() {
                parts.push(format!("\"{run}\""));
                run.clear();
            }
            parts.push(format!("Chr({b})"));
        }
    }
    if !run.is_empty() || parts.is_empty() {
        parts.push(format!("\"{run}\""));
    }
    parts.join(" & ")
}

impl LinearSyntax for FreeBasic {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        text.to_string()
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "1" } else { "0" })
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        format!("Az{ty}_{variant}")
    }

    fn type_name(&self, ty: &str) -> String {
        format!("Az{ty}")
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("ARRAY {} Az{elem}", n.saturating_sub(1))
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let e = self.call_expr(class, method, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let e = self.variant_expr(ty, variant, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn union(
        &self,
        target: &str,
        _ty: &str,
        _variant: &str,
        tag: usize,
        _payload: Option<&str>,
    ) -> Vec<String> {
        // unreachable: `limitation` rejects every hand-built union
        vec![format!("{target}.tag = {tag}")]
    }

    fn set_field(&self, target: &str, _ty: &str, field: &str, value: &str) -> String {
        format!("{target}.{field} = {value}")
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("{arr}({index}) = {value}")
    }

    fn vec_from_array(&self, target: &str, ty: &str, elem: &str, arr: &str, count: &str) -> Vec<String> {
        let e = self.vec_expr(ty, elem, arr, count).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("{target} = Az{ty}_create()")]
    }

    fn string(&self, target: &str, s: &str) -> Vec<String> {
        vec![format!("{target} = CssStr({})", basic_string(s))]
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "azul.bi declares no type for `{ty}` (or for the CssPropertyValue<T> in its \
                 payload)"
            )),
            Expr::Float { text, .. } if text == "nan" || text.ends_with("inf") => {
                Some("NaN / infinity has no FreeBASIC literal".to_string())
            }
            _ => None,
        }
    }

    fn call_expr(&self, class: &str, method: &str, args: &[String]) -> Option<String> {
        Some(apply(&format!("Az{class}_{}", snake_to_lower_camel(method)), args))
    }

    fn variant_expr(&self, ty: &str, variant: &str, args: &[String]) -> Option<String> {
        Some(apply(&format!("Az{ty}_{}", variant_ctor_method(variant)), args))
    }

    fn struct_expr(&self, ty: &str, fields: &[(String, String)]) -> Option<String> {
        let values: Vec<&str> = fields.iter().map(|(_, v)| v.as_str()).collect();
        Some(format!("Type<Az{ty}>({})", values.join(", ")))
    }

    fn string_expr(&self, s: &str) -> Option<String> {
        Some(format!("CssStr({})", basic_string(s)))
    }

    fn vec_expr(&self, ty: &str, _elem: &str, arr: &str, count: &str) -> Option<String> {
        Some(format!("Az{ty}_copyFromPtr(@{arr}(0), {count})"))
    }

    fn vec_empty_expr(&self, ty: &str) -> Option<String> {
        Some(format!("Az{ty}_create()"))
    }
}

fn fn_name(item: &Item) -> String {
    item.name.upper_camel()
}

fn item_fn(item: &Item) -> (bool, String) {
    let name = fn_name(item);
    if let Some(reason) = item_blocker(&FreeBasic, item) {
        return (
            false,
            format!("' {name}: not expressible with the FreeBASIC bindings: {reason}\n"),
        );
    }
    let st = lower_to_statements(&FreeBasic, &item.value);
    let mut out = String::new();
    for line in linear_comments(item, &st) {
        out.push_str(&format!("' {line}\n"));
    }
    out.push_str(&format!("Function {name}() As Az{}\n", item.ty));
    for (n, t) in &st.decls {
        match t.strip_prefix("ARRAY ") {
            Some(rest) => {
                let (last, ty) = rest.split_once(' ').unwrap_or((rest, ""));
                out.push_str(&format!("    Dim {n}(0 To {last}) As {ty}\n"));
            }
            None => out.push_str(&format!("    Dim {n} As {t}\n")),
        }
    }
    for s in &st.body {
        out.push_str(&format!("    {s}\n"));
    }
    out.push_str(&format!("    Return {}\nEnd Function\n", st.result));
    (true, out)
}

const CSS_STR: &str = "Function CssStr(ByRef s As Const String) As AzString
    Return AzString_copyFromBytes(CPtr(UByte Ptr, StrPtr(s)), 0, Len(s))
End Function
";

impl CodegenBackend for FreeBasic {
    fn lang(&self) -> &'static str {
        "freebasic"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["fb", "fbc"]
    }

    fn display_name(&self) -> &'static str {
        "FreeBASIC"
    }

    fn extension(&self) -> &'static str {
        "bas"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "' Generated by azul-css codegen (FreeBASIC). Do not edit by hand.\n#include once \
             \"azul.bi\"\n",
        );
        if module_any(m, &|e| matches!(e, Expr::Str(_))) {
            out.push('\n');
            out.push_str(CSS_STR);
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "' Copy target/codegen/azul.bi and libazul here, then:\n'   fbc main.bas -p . -l \
             azul && ./main\n#include \"styles.bas\"\n\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = fn_name(item);
            main.push_str(&format!(
                "Dim {name}Value As Az{} = {name}()\nPrint \"{name}: \"; {name}Value.len; \" \
                 properties\"\n",
                item.ty
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.bas".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.bas".to_string(),
                contents: main,
            },
        ]
    }
}
